// Long-run return to player of each game at the player's current upgrades:
// slots from the table generated by scripts/odds.mjs, roulette and blackjack
// exactly. Also how often a round and a 1,000-round session end ahead, from
// the same table for every game. Classic script: globalThis.BotterOdds in the extension, require()
// in Node.
(function (root) {
  const TABLE = root.BotterOddsTable ?? require('./odds-table.js');
  const BJ = root.BotterBlackjack ?? require('./blackjack.js');

  const level = (upgrades, key, max) => Math.max(0, Math.min(max, upgrades?.[key] ?? 0));

  // Upgrades that change each game's odds, with their max level, in the order
  // of the table keys.
  const UPGRADES = {
    blaze: [['lucky', 5], ['wild', 5], ['star', 5]],
    skeleton: [['team', 4], ['wild', 4], ['deploy', 3]],
    slotingi: [['crown', 3], ['gulas', 4], ['mint', 3]],
    blackjack: [['bjpay', 2], ['ties', 4], ['soft17', 1], ['double', 1]],
    roulette: [['zeros', 2]],
  };
  const key = (game, own) => UPGRADES[game].map(([name, max]) => level(own, name, max)).join('');

  // Roulette pays 36 units per unit on a hit, outside bets included, on a
  // wheel of 37 numbers plus the zeros the upgrade has not removed yet.
  const ROULETTE_EXTRA_ZEROS = 2;

  const blackjackCache = new Map();
  function blackjackRtp(upgrades) {
    const rules = BJ.rulesFromUpgrades(upgrades);
    const id = JSON.stringify(rules);
    if (!blackjackCache.has(id)) blackjackCache.set(id, 1 + BJ.solverFor(rules).houseEdge());
    return blackjackCache.get(id);
  }

  // Return to player as a share of the wager, or null for a game without a
  // model. blazeMode is the scatter rule the server uses ('symbols' or 'reels').
  function rtp(game, upgrades, blazeMode = 'reels') {
    const own = upgrades?.[game];
    switch (game) {
      case 'blaze':
        return TABLE.blaze[blazeMode]?.[key(game, own)] ?? null;
      case 'skeleton':
      case 'slotingi':
        return TABLE[game][key(game, own)] ?? null;
      case 'roulette':
        return 36 / (37 + ROULETTE_EXTRA_ZEROS - level(own, 'zeros', ROULETTE_EXTRA_ZEROS));
      case 'blackjack':
        return blackjackRtp(own);
      default:
        return null;
    }
  }

  // House edge per game (negative when the player is ahead), for the games
  // that have a model.
  function edges(games, upgrades, blazeMode) {
    const out = {};
    for (const game of games) {
      const r = rtp(game, upgrades, blazeMode);
      if (r !== null) out[game] = 1 - r;
    }
    return out;
  }

  // Simulated { win, ahead, gain, variance, bigs }: the share of rounds that
  // return more than the bet and of 1,000-round sessions that end ahead, the
  // mean net profit per credit staked of the rounds that end ahead, the
  // variance of one round's return per credit and the share of rounds paying a
  // big, mega and super win ([10x, 25x, 50x] the bet), or null without a model.
  // Fields are null in a table generated before they were recorded.
  function chances(game, upgrades, blazeMode = 'reels') {
    if (!UPGRADES[game]) return null;
    const games = TABLE.chances?.[game];
    const row = (game === 'blaze' ? games?.[blazeMode] : games)?.[key(game, upgrades?.[game])];
    if (!row) return null;
    const bigs = row.length > 4 ? row.slice(4, 7) : null;
    return { win: row[0], ahead: row[1], gain: row[2] ?? null, variance: row[3] ?? null, bigs };
  }

  // One simulated figure (see chances) per game, for the games that have it.
  function pick(field) {
    return (games, upgrades, blazeMode) => {
      const out = {};
      for (const game of games) {
        const value = chances(game, upgrades, blazeMode)?.[field];
        if (value !== null && value !== undefined) out[game] = value;
      }
      return out;
    };
  }
  const winRates = pick('win');
  const gains = pick('gain');
  const variances = pick('variance');
  const bigRates = pick('bigs');

  // Every upgrade combination of a game with its return and chances, from no
  // upgrades to all maxed: [{ upgrades: { name: level }, rtp, win, ahead }].
  function table(game, blazeMode = 'reels') {
    let all = [{}];
    for (const [name, max] of UPGRADES[game] ?? []) {
      all = all.flatMap((own) => Array.from({ length: max + 1 }, (_, l) => ({ ...own, [name]: l })));
    }
    return all.map((own) => ({
      upgrades: own,
      rtp: rtp(game, { [game]: own }, blazeMode),
      ...chances(game, { [game]: own }, blazeMode),
    }));
  }

  // Scatter rule that reproduces more of the recorded Blaze spins. Until there
  // are enough spins, the rule with the lower return, so the grinder does not
  // count on a player edge it has not confirmed.
  function blazeMode(check, minSpins = 50) {
    const { symbols, reels } = check ?? {};
    if (!symbols || !reels || symbols.total < minSpins) return 'reels';
    return symbols.match > reels.match ? 'symbols' : 'reels';
  }

  // Whether the recorded spins settle the scatter rule: enough of them, and one
  // rule matches more than the other. Only about 1 spin in 110 pays differently.
  function blazeDecided(check, minSpins = 50) {
    const { symbols, reels } = check ?? {};
    return !!symbols && !!reels && symbols.total >= minSpins && symbols.match !== reels.match;
  }

  const api = { UPGRADES, rtp, edges, chances, winRates, gains, variances, bigRates, table, blazeMode, blazeDecided };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.BotterOdds = api;
})(globalThis);
